using WAID.Application.Services;using WAID.Infrastructure.Persistence;namespace WAID.Infrastructure.Tests;public sealed class ReliabilityTimelinePersistenceTests
{[Fact]public async Task Paged_queries_are_stable_filtered_and_include_incident_detail(){var path=Path.Combine(Path.GetTempPath(),$"waid-timeline-{Guid.NewGuid():N}.db");try{var db=new WaidDatabase($"Data Source={path};Pooling=False");await db.InitializeAsync(CancellationToken.None);var repo=new SqliteReliabilityTimelineRepository(db);var start=DateTimeOffset.UtcNow;var events=Enumerable.Range(0,205).Select(i=>new ReliabilityTimelineEvent($"{i:D4}",i%2==0?ReliabilityEventKind.Crash:ReliabilityEventKind.Update,start.AddMinutes(-(i/2)), $"Event {i}","summary",ReliabilitySeverity.Warning,"subject",new("test",i.ToString(),$"test:{i}"),new Dictionary<string,string>(),ReliabilityTimelineProjector.ProjectionVersion)).ToArray();var incident=new ReliabilityIncident("incident",start.AddMinutes(-2),start,"group",ReliabilitySeverity.Warning,[events[0].Id,events[1].Id],ReliabilityTimelineProjector.GroupingVersion,"Possible association; not proof of causation.");await repo.ReplaceAsync(new(ReliabilityTimelineProjector.ProjectionVersion,ReliabilityTimelineProjector.GroupingVersion,start,events,[incident]),CancellationToken.None);var first=await repo.QueryAsync(new(0,50),CancellationToken.None);var second=await repo.QueryAsync(new(1,50),CancellationToken.None);Assert.Equal(205,first.TotalCount);Assert.Equal(50,first.Items.Count);Assert.Empty(first.Items.Select(x=>x.Id).Intersect(second.Items.Select(x=>x.Id)));Assert.Equal(first.Items.OrderByDescending(x=>x.OccurredAtUtc).ThenBy(x=>x.Id).Select(x=>x.Id),first.Items.Select(x=>x.Id));var crashes=await repo.QueryAsync(new(0,200,Kind:ReliabilityEventKind.Crash),CancellationToken.None);Assert.Equal(103,crashes.TotalCount);var loadedIncident=await repo.GetIncidentAsync("incident",CancellationToken.None);Assert.NotNull(loadedIncident);Assert.Equal(incident.Id,loadedIncident.Id);Assert.Equal(incident.EventIds,loadedIncident.EventIds);Assert.Equal(incident.CorrelationLabel,loadedIncident.CorrelationLabel);Assert.Single(await repo.GetRecentIncidentsAsync(10,CancellationToken.None));}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(File.Exists(path))File.Delete(path);}}
 [Fact]public async Task Projection_replace_is_atomic_and_does_not_modify_source_tables(){var path=Path.Combine(Path.GetTempPath(),$"waid-timeline-source-{Guid.NewGuid():N}.db");try{var db=new WaidDatabase($"Data Source={path};Pooling=False");await db.InitializeAsync(CancellationToken.None);await using(var c=db.OpenConnection()){await using var q=c.CreateCommand();q.CommandText="INSERT INTO scan_sessions(id,started_utc,completed_utc,status,framework_version)VALUES('source','2026-01-01T00:00:00Z','2026-01-01T00:00:01Z','Completed','1')";await q.ExecuteNonQueryAsync();}var repo=new SqliteReliabilityTimelineRepository(db);await repo.ReplaceAsync(new("v","g",DateTimeOffset.UtcNow,[],[]),CancellationToken.None);await using var check=db.OpenConnection();await using var count=check.CreateCommand();count.CommandText="SELECT COUNT(*) FROM scan_sessions";Assert.Equal(1,Convert.ToInt32(await count.ExecuteScalarAsync()));}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(File.Exists(path))File.Delete(path);}}
}
